import os
import sys
import shutil
import json
import re
import argparse
from pathlib import Path
import yaml

BASE_DIR = Path(__file__).resolve().parents[2]
KB_DIR = BASE_DIR / "Knowledge-OS"
GENERATED_DIR = KB_DIR / "07-Agent-Rules" / "generated"
MANIFEST_PATH = GENERATED_DIR / ".manifest.json"

HEADER_COMMENT = """# =================================================================
# THIS FILE IS AUTOMATICALLY GENERATED BY tools/compile_rules.py
# DO NOT EDIT THIS FILE DIRECTLY. EDIT SOURCE SOPs IN Knowledge-OS/
# =================================================================
"""

def compile_rules(dry_run=False):
    compiled_rules = {}
    seen_rule_ids = {}
    parsing_errors = []

    source_files = sorted(list(KB_DIR.rglob("*.md")))

    for file_path in source_files:
        if "07-Agent-Rules" in file_path.parts or file_path.name == "Dashboard.md":
            continue

        try:
            content = file_path.read_text(encoding="utf-8")
            match = re.search(r"^---\s*\n(.*?)\n---", content, re.DOTALL)
            if not match:
                continue

            data = yaml.safe_load(match.group(1))
            if not data or "agent_rules" not in data or not isinstance(data["agent_rules"], list):
                continue

            doc_id = data.get("id", "UNKNOWN")
            domain = data.get("domain", "general").strip().lower()
            version = data.get("version", "1.0.0")

            if domain not in compiled_rules:
                compiled_rules[domain] = []

            for item in data["agent_rules"]:
                if not isinstance(item, dict):
                    parsing_errors.append(f"[{file_path.name}] agent_rules item must be a dictionary.")
                    continue

                rule_item_id = item.get("id")
                rule_text = item.get("rule")
                priority = item.get("priority", 50)
                enforcement = item.get("enforcement", "must")
                overridable = item.get("overridable", True)

                if not rule_item_id or not rule_text:
                    parsing_errors.append(f"[{file_path.name}] Missing 'id' or 'rule' in agent_rules item.")
                    continue

                if rule_item_id in seen_rule_ids:
                    parsing_errors.append(
                        f"Duplicate Rule ID '{rule_item_id}' found in {file_path.name} "
                        f"(previously defined in {seen_rule_ids[rule_item_id]})"
                    )
                else:
                    seen_rule_ids[rule_item_id] = file_path.name

                compiled_rules[domain].append({
                    "id": rule_item_id,
                    "doc_id": doc_id,
                    "version": version,
                    "priority": priority,
                    "enforcement": enforcement,
                    "overridable": overridable,
                    "rule": rule_text.strip()
                })

        except Exception as e:
            parsing_errors.append(f"Fatal YAML/Parse Exception in {file_path.name}: {str(e)}")

    if parsing_errors:
        print("\n[ERROR] Rule compilation failed:")
        for err in parsing_errors:
            print(f"  - {err}")
        print("\nBuild aborted to prevent rule drift.\n")
        sys.exit(1)

    if dry_run:
        print("\n[DRY RUN] All SOP Frontmatters and Rule IDs are valid. No files written.\n")
        return

    if GENERATED_DIR.exists():
        shutil.rmtree(GENERATED_DIR)
    GENERATED_DIR.mkdir(parents=True, exist_ok=True)

    manifest_data = {"generated_files": [], "total_rules": 0}

    for domain, rules in compiled_rules.items():
        output_file_name = f"{domain}-rules.md"
        output_path = GENERATED_DIR / output_file_name

        rules.sort(key=lambda x: (-x["priority"], x["id"]))

        with open(output_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(HEADER_COMMENT + "\n")
            f.write(f"# Compiled Domain Rules: {domain.upper()}\n\n")
            for r in rules:
                override_tag = "NON-OVERRIDABLE" if not r["overridable"] else "OVERRIDABLE"
                f.write(f"- [{r['id']}] [{r['enforcement'].upper()}] [{override_tag}] {r['rule']} (Source: {r['doc_id']}@v{r['version']})\n")

        manifest_data["generated_files"].append(output_file_name)
        manifest_data["total_rules"] += len(rules)
        print(f"[OK] Generated: {output_path} ({len(rules)} rules)")

    with open(MANIFEST_PATH, "w", encoding="utf-8", newline="\n") as f:
        json.dump(manifest_data, f, indent=2)

    print(f"\nRule Compilation Succeeded! Total Rules: {manifest_data['total_rules']}\n")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Knowledge-OS Rule Compiler")
    parser.add_argument("--dry-run", action="store_true", help="Validate frontmatters without writing files")
    args = parser.parse_args()
    compile_rules(dry_run=args.dry_run)